project_budget_details_paginated_query:
query BusinessPlanningBudgetDetailsPaginated($budgetId: ID!, $budgetDetailsInput: BusinessPlanning_FetchBudgetDetailsInput) {
  businessPlanningBudget(budgetId: $budgetId) {
    budgetId
    budgetName
    budgetType
    linkedEntityId
    total
    state
    budgetDetailsPaginated(budgetDetailsInput: $budgetDetailsInput) {
      edges {
        node { sequenceId order type itemId unitCost quantity amount description date accountId klassId locationId }
        cursor
      }
      pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
      totalCount
    }
  }
}

